import React, { useState } from "react";

interface PromptOptions {
  background: string;
  character: string;
  event: string;
  camera: string;
  lighting: string;
}

export default function VideoGenerator() {
  const [promptOptions, setPromptOptions] = useState<PromptOptions>({
    background: "maintain original style(reference image as a background)",
    character: "Two masked robbers that are half size of the fence in the reference image",
    event: "Break down the fence(carrying a crowbar and bolt cutters) and come in, from right side of the reference image to left side of the image",
    camera: "No camera movement , fixed position like CCTV",
    lighting: "soft dark light, and CCTV style",
  });


  const [model, setModel] = useState<string>("sora-2");
  const [seconds, setSeconds] = useState("8");
  const [size, setSize] = useState("1280x720");
  const [file, setFile] = useState<File | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState("idle");
  
  const [width, setWidth] = useState(1280);
  const [height, setHeight] = useState(720);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
  };

  const handlePromptChange = (field: keyof PromptOptions, value: string) => {
    setPromptOptions((prev) => ({ ...prev, [field]: value }));
  };

  const getVideo = async () => {
    setStatus("starting");
    setProgress(0);
    setVideoUrl(null);

    let imageBase64: string | undefined;
    if (file) {
      imageBase64 = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
    }

    let data;
    try {
      const res = await fetch("/api/generate-video", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ promptOptions, imageBase64, seconds: seconds, size, model }),
      });

      try {
        data = await res.json();
      } catch {
        const text = await res.text();
        console.error("Non-JSON response from server:", text);
        setStatus("failed");
        return;
      }

      if (data.error) {
        console.error(data.error);
        setStatus("failed");
        return;
      }
    } catch (err) {
      console.error("Fetch error:", err);
      setStatus("failed");
      return;
    }

    // ...existing code...
    const array = new Uint8Array(data.videoContent);
    const blob = new Blob([array], { type: "video/mp4" });
    const url = URL.createObjectURL(blob);
    setVideoUrl(url);
    setStatus("completed");
    setProgress(100);

    // automatically download the video file
    try {
      const timestamp = Date.now();
      const videoFilename = `video-${timestamp}.mp4`;
      const a = document.createElement("a");
      a.href = url;
      a.download = videoFilename;
      // append to DOM to ensure click works on all browsers
      document.body.appendChild(a);
      a.click();
      a.remove();

      // create and download JSON containing prompts/metadata
      const promptsJson = {
        promptOptions,
        seconds,
        size,model,
        sourceFilename: file?.name ?? null,
        generatedAt: new Date(timestamp).toISOString(),
      };
      const jsonBlob = new Blob([JSON.stringify(promptsJson, null, 2)], {
        type: "application/json",
      });
      const jsonUrl = URL.createObjectURL(jsonBlob);
      const jsonFilename = `video-prompts-${timestamp}.json`;
      const a2 = document.createElement("a");
      a2.href = jsonUrl;
      a2.download = jsonFilename;
      document.body.appendChild(a2);
      a2.click();
      a2.remove();

      // revoke object URLs after a short delay
      setTimeout(() => {
        URL.revokeObjectURL(url);
        URL.revokeObjectURL(jsonUrl);
      }, 60_000);
    } catch (err) {
      console.error("Auto-download failed:", err);
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Image to Video Generator</h1>

        <div style={{ marginBottom: 10 }}>
        <label>Model:</label>
        <select value={model} onChange={(e) => setModel(e.target.value)}>
          <option value="sora-2">sora 2</option>
          <option value="sora-2-pro">sora 2 pro</option>
          <option value="veo-3.1">veo 3.1</option>
        </select>
      </div>

      {(["background", "character", "event", "camera", "lighting"] as (keyof PromptOptions)[]).map((field) => (
        <div key={field} style={{ marginBottom: 10 }}>
          <label>{field.charAt(0).toUpperCase() + field.slice(1)}:</label>
          <input
            value={promptOptions[field]}
            onChange={(e) => handlePromptChange(field, e.target.value)}
          />
        </div>
      ))}

      <div style={{ marginBottom: 10 }}>
        <label>Seconds:</label>
        <select value={seconds} onChange={(e) => setSeconds(e.target.value)}>
          <option value={4}>4</option>
          <option value={8}>8</option>
          <option value={12}>12</option>
        </select>
      </div>

      {/* <div style={{ marginBottom: 10 }}>
        <label>Width:</label>
        <input type="number" value={width} onChange={(e) => setWidth(Number(e.target.value))} />
        <label>Height:</label>
        <input type="number" value={height} onChange={(e) => setHeight(Number(e.target.value))} />
      </div> */}

      <div style={{ marginBottom: 10 }}>
        <label>size:</label>
        <select value={size} onChange={(e) => setSize(e.target.value)}>
          <option value={'720x1280'}>720x1280</option>
          <option value={'1280x720'}>1280x720</option>
          <option value={'1024x1792'}>1024x1792</option>
          <option value={'1792x1024'}>1792x1024</option>
        </select>
      </div>

      <div style={{ marginBottom: 10 }}>
        <label>Reference Image:</label>
        <input type="file" accept="image/*" onChange={handleFileChange} />
      </div>

      <button onClick={getVideo}>Generate Video</button>

      <p>Status: {status}</p>
      <div style={{ width: "300px", height: "20px", background: "#eee", marginTop: 10 }}>
        <div style={{ width: `${progress}%`, height: "100%", background: "#4caf50" }}></div>
      </div>

      {videoUrl && (
        <div style={{ marginTop: 20 }}>
          <video src={videoUrl} controls width={400} />
          <div>
            <a href={videoUrl} download="video.mp4">Download Video</a>
          </div>
        </div>
      )}
    </div>
  );
}